import java.io.*;
import java.util.*;
public class Main {
  static class MyLinkedList {
    static class Node { int val; Node next; Node(int v){val=v;} }
    Node head; int size;
    void addAtHead(int val){ Node n=new Node(val); n.next=head; head=n; size++; }
    void addAtTail(int val){
      Node n=new Node(val); if(head==null){head=n;size++;return;}
      Node p=head; while(p.next!=null)p=p.next; p.next=n; size++;
    }
    void addAtIndex(int index,int val){
      if(index<0 || index>size)return;
      if(index==0){addAtHead(val);return;}
      if(index==size){addAtTail(val);return;}
      Node p=head; for(int i=1;i<index;i++)p=p.next;
      Node n=new Node(val); n.next=p.next; p.next=n; size++;
    }
    void deleteAtIndex(int index){
      if(index<0||index>=size||head==null)return;
      if(index==0){head=head.next;size--;return;}
      Node p=head; for(int i=1;i<index;i++)p=p.next;
      p.next=p.next.next; size--;
    }
    int get(int index){
      if(index<0||index>=size)return -1;
      Node p=head; for(int i=0;i<index;i++)p=p.next; return p.val;
    }
  }
  public static void main(String[] a)throws Exception{
    BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
    int q=Integer.parseInt(br.readLine().trim()); MyLinkedList list=new MyLinkedList();
    StringBuilder out=new StringBuilder();
    for(int z=0;z<q;z++){
      String[] p=br.readLine().trim().split("\\s+");
      switch(p[0]){
        case "addAtHead": list.addAtHead(Integer.parseInt(p[1])); break;
        case "addAtTail": list.addAtTail(Integer.parseInt(p[1])); break;
        case "addAtIndex": list.addAtIndex(Integer.parseInt(p[1]),Integer.parseInt(p[2])); break;
        case "deleteAtIndex": list.deleteAtIndex(Integer.parseInt(p[1])); break;
        case "get":
          if(out.length()>0)out.append('\n');
          out.append(list.get(Integer.parseInt(p[1])));
          break;
      }
    }
    System.out.print(out);
  }
}

